input.script:
() => {
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (checkbox) {
    checkbox.click();
    return 'clicked';
  }
  return 'no checkbox found';
}

() => {
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (checkbox) {
    checkbox.click();
    checkbox.dispatchEvent(new Event('click', { bubbles: true }));
    checkbox.dispatchEvent(new MouseEvent('mousedown', { bubbles: true }));
    checkbox.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));
    return 'clicked checkbox via JS';
  }
  return 'no checkbox found';
}

() => {
  // Check if iframe is present
  const iframe = document.querySelector('iframe');
  if (iframe) {
    return {iframeFound: true, src: iframe.src};
  }

  // Look for any checkbox or clickable element
  const checkbox = document.querySelector('input[type="checkbox"]');
  if (checkbox) {
    const rect = checkbox.getBoundingClientRect();
    return { 
      checkboxFound: true, 
      x: rect.x, 
      y: rect.y, 
      width: rect.width, 
      height: rect.height,
      checked: checkbox.checked,
      visible: rect.width > 0 && rect.height > 0
    };
  }
  return 'no iframe or checkbox found';
}

